#!/usr/bin/env bash
set -euo pipefail

# Applies the sitewide Blush & Ink CTA + surface sweep (solid-fill CTAs,
# no outlines; remaining bg-warmgray surfaces migrated to the blush
# palette) to a fresh clone of go-website, on a new branch.
#
# Usage: run from a clean directory that doesn't already have ./go-website:
#   bash apply_blush_ink_cta_sweep.sh

REPO_URL="https://github.com/yoosuf0806/go-website.git"
BRANCH="claude/blush-ink-cta-sweep"

if [ -d go-website ]; then
  echo "A ./go-website directory already exists here — remove or rename it first." >&2
  exit 1
fi

echo "Cloning fresh main..."
git clone "$REPO_URL" go-website
cd go-website
git checkout -b "$BRANCH"

echo "Applying patch..."
base64 -d <<'PATCH_B64' | git am

PATCH_B64

echo
echo "Patch applied cleanly on branch $BRANCH."
echo "Next steps:"
echo "  1. git push -u origin $BRANCH"
echo "  2. Open a PR: https://github.com/yoosuf0806/go-website/compare/main...$BRANCH"
